  select count(*) into v_n from public.supplier_contracts
   where organization_id = v_org and supplier_id is null;
  if v_n <> 0 then
    raise exception 'supplier contract import: % row(s) failed to resolve a supplier', v_n;
  end if;
  select count(*) into v_n from public.supplier_contracts
   where organization_id = v_org and amends_contract_id is not null;
  if v_n <> 5 then
    raise exception 'supplier contract import: expected 5 amendment links, found %', v_n;
  end if;
end $$;
